package localchat;
import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.AtomicInteger;import javax.swing.*;
/** Explicit interaction boundaries, pending drafts and zero-inference ghost suggestions. */
public final class ComposerAssistTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static List<Component> all(Component c){List<Component> out=new ArrayList<>();out.add(c);if(c instanceof Container box)for(Component child:box.getComponents())out.addAll(all(child));return out;}
 static Map<String,Object> questions(){List<Object> qs=new ArrayList<>();for(int i=1;i<=3;i++)qs.add(Json.obj("id","q"+i,"question",i==1?"Retine ca trebuie copiat fara confirmare?":"Copy confirmed group "+i+"?","options",List.of("Da","Nu")));return Json.obj("message","Choose the confirmed groups","questions",qs,"suggestions",List.of());}
 static Map<String,Object> suggestions(){return Json.obj("message","Next step","questions",List.of(),"suggestions",List.of("Verifica raportul final al proiectului curent.","Arata verificarile ramase."));}
 static List<ChatClient.Message> history(Object request){return List.of(ChatClient.Message.user("Check this project"),ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("request","localchat_interaction",(Map<String,Object>)request)),"fixture"),ChatClient.Message.toolResult("request",Json.write(Json.obj("status","waiting_user","executed",false)),false));}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  check(ComposerAssist.parse(questions()).questions().size()==3,"structured questions bounded and parsed");for(Object bad:List.of(Json.obj("message","","questions",List.of(),"suggestions",List.of()),Json.obj("message","","questions",List.of(),"suggestions",List.of("/run unexpected")),Json.obj("message","","questions",List.of(Json.obj("id","q","question","?","options",List.of("same","same"))),"suggestions",List.of()))){try{ComposerAssist.parse(bad);throw new AssertionError("bad interaction accepted");}catch(IllegalArgumentException expected){checks++;}}
  String legacy="Propunere: confirma.\n1. Copiere TR/BD + DWG — da/nu?\n2. Copiere GP — da/nu?\n3. Copiere PP01 — da/nu?\nAstept confirmarea.";check(ComposerAssist.detect(legacy).questions().size()==3,"reported legacy prose becomes three concrete choices");check(ComposerAssist.detect("What is a PDF? Here is an explanation.")==null,"ordinary prose does not invent clarification forms");
  FeatureTest.edt(()->{
   var input=new ComposerAssist.GhostInput();ComposerEditing.History editing=ComposerEditing.install(input);AtomicInteger submits=new AtomicInteger();String[] answer={""};var assist=new ComposerAssist(input,text->{submits.incrementAndGet();answer[0]=text;});input.setText("pending message");assist.present(questions(),"request");check(assist.waiting()&&!assist.send.isEnabled()&&input.getText().equals("pending message"),"no defaults, no overwrite and pending text remains editable");
   var options=all(assist).stream().filter(c->c instanceof JRadioButton).map(c->(JRadioButton)c).toList();var fields=all(assist).stream().filter(c->c instanceof JTextField).map(c->(JTextField)c).toList();options.get(0).doClick();fields.get(1).setText("Doar dupa verificarea raportului");check(!assist.send.isEnabled(),"partial choices cannot submit");fields.get(0).setText("Own first answer");check(!options.get(0).isSelected(),"free text clears conflicting preset choice");options.get(0).doClick();check(fields.get(0).getText().isEmpty(),"explicit option clears stale free text");String snapshot=assist.snapshot();var restored=new ComposerAssist(new ComposerAssist.GhostInput(),text->{});restored.restore(history(questions()),snapshot);check(restored.snapshot().contains("Doar dupa")&&!restored.send.isEnabled(),"partial free answer persists across restore");
   options.get(5).doClick();check(assist.send.isEnabled(),"all explicit answers enable submit");assist.busy(true);check(!assist.send.isEnabled(),"busy turn cannot submit choices");assist.busy(false);assist.send.doClick();check(submits.get()==1&&answer[0].contains("Doar dupa")&&answer[0].contains("Nu"),"explicit submission contains choices and free answer exactly once");check(input.getText().equals("pending message"),"standalone choice form does not edit pending message");
   input.setText("");editing.reset();assist.present(suggestions(),"suggestion");check(input.getText().isEmpty()&&!input.ghost.isBlank()&&submits.get()==1,"ghost is display only, absent from document and sends");check(assist.acceptFirst()&&input.getText().contains("Verifica raportul"),"Tab acceptance inserts optional draft only");editing.undo.actionPerformed(null);check(input.getText().isEmpty(),"accepted suggestion is undoable in one edit");assist.present(suggestions(),"second");input.setText("my own draft");check(!assist.acceptFirst()&&input.getText().equals("my own draft"),"suggestion cannot replace user text");assist.clear();check(input.getText().equals("my own draft")&&!assist.isVisible(),"clearing UI preserves draft");
   for(String lang:I18n.CODES){I18n.setLanguage(lang);assist.present(questions(),"appearance");assist.translate();check(assist.send.getText().equals(I18n.text("Trimite raspunsurile")),"localized submit "+lang);check(assist.close.getToolTipText().equals(I18n.text("Inchide propunerile")),"localized dismiss "+lang);}
   I18n.setLanguage("ro");var state=new Conversations.State();state.interactionState=snapshot;state.interactionReplyDraft=true;var loaded=Conversations.State.fromJson(state.toJson(),0);check(loaded.interactionState.equals(snapshot)&&loaded.interactionReplyDraft,"conversation JSON preserves partial interaction draft");
   assist.restore(List.of(ChatClient.Message.user("new chat")),snapshot);check(!assist.waiting()&&!assist.isVisible(),"no cross-chat stale form");var unconfirmed=new ArrayList<>(history(questions()));unconfirmed.remove(unconfirmed.size()-1);assist.restore(unconfirmed,"");check(!assist.waiting(),"unexecuted tool declaration is not a confirmed pending interaction");
  });
  Path mustNotWrite=home.resolve("must-not-write.txt");Object write=Json.obj("id","write","type","function","function",Json.obj("name","write_file","arguments",Json.write(Json.obj("path",mustNotWrite.toString(),"content","NOT AUTHORIZED"))));Object ask=Json.obj("id","request","type","function","function",Json.obj("name",ComposerAssist.TOOL,"arguments",Json.write(questions())));String response=Json.write(Json.obj("choices",List.of(Json.obj("message",Json.obj("content","","tool_calls",List.of(write,ask))))));
  try(var server=new FeatureTest.Server(FeatureTest.json(response),FeatureTest.json(FeatureTest.answer("Explicit answers received",30,5)))){
   LocalChat[] app={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());app[0].setSize(1500,1050);app[0].addNotify();app[0].validate();Properties prefs=FeatureTest.field(app[0],"config");prefs.setProperty("memory.enabled","true");prefs.setProperty("memory.allowTools","true");((JComboBox<?>)FeatureTest.field(app[0],"permissionBox")).setSelectedIndex(1);});NormalModeTest.ask(app[0],"Verifica proiectul si intreaba-ma ce grupuri sa copiez.");
   FeatureTest.edt(()->{ComposerAssist assist=FeatureTest.field(app[0],"composerAssist");check(assist.waiting()&&server.requests.size()==1,"interaction pauses without extra inference");check(!Files.exists(mustNotWrite),"sibling mutation before interaction is never executed");for(int appearance=0;appearance<2;appearance++){((JComboBox<?>)FeatureTest.field(app[0],"themeBox")).setSelectedIndex(appearance);app[0].validate();BufferedImage image=new BufferedImage(app[0].getWidth(),app[0].getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();app[0].getRootPane().printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",home.resolve(appearance==1?"interaction-dark.png":"interaction-light.png").toFile());check(assist.isVisible()&&assist.getHeight()>50,"question form is visible beside editable composer");}check(NormalModeTest.history(app[0]).stream().anyMatch(m->m.role.equals("tool")&&m.isError),"unexecuted sibling has explicit archival result");AttachmentTest.input(app[0]).setText("Mesaj suplimentar in asteptare");FeatureTest.call(app[0],"send",new Class<?>[]{});check(server.requests.size()==1&&AttachmentTest.input(app[0]).getText().contains("asteptare"),"send preserves pending message until choices are supplied");for(Component c:all(assist))if(c instanceof JRadioButton radio&&("q1".equals(radio.getClientProperty("interaction.question"))?"Nu":"Da").equals(radio.getClientProperty("interaction.option")))radio.doClick();assist.send.doClick();});FeatureTest.idle(app[0]);
   FeatureTest.edt(()->{check(server.requests.size()==2,"one explicit submission produces one next request");var log=NormalModeTest.history(app[0]);String submitted=log.stream().filter(m->m.role.equals("user")).reduce((a,b)->b).orElseThrow().content;check(submitted.contains("Copy confirmed group 3?")&&submitted.contains("Mesaj suplimentar"),"submitted answers and queued draft are combined without loss");check(new LocalMemories(home.resolve("app"),FeatureTest.field(app[0],"config")).all().isEmpty(),"model question text and a negative choice cannot become a permanent rule");check(!AttachmentTest.state(app[0]).interactionReplyDraft,"submitted interaction origin clears at turn boundary");check(!FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"answered form does not reappear after final reply");ComposerAssist suggestionPanel=FeatureTest.field(app[0],"composerAssist");suggestionPanel.present(suggestions(),"tab-binding");JTextArea editor=AttachmentTest.input(app[0]);Object tab=editor.getInputMap().get(KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_TAB,0));editor.getActionMap().get(tab).actionPerformed(null);check(editor.getText().contains("Verifica raportul")&&server.requests.size()==2,"bound Tab action inserts suggestion without sending");editor.getActionMap().get("localchat.undo").actionPerformed(null);check(editor.getText().isEmpty(),"bound Undo reverses accepted suggestion");log.add(ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("later-question",ComposerAssist.TOOL,questions())),"fixture"));log.add(ChatClient.Message.toolResult("later-question",Json.write(Json.obj("status","waiting_user")),false));FeatureTest.call(app[0],"renderHistory",new Class<?>[]{});check(FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"new current-context clarification can be restored");AttachmentTest.state(app[0]).interactionReplyDraft=true;AttachmentTest.input(app[0]).setText("Generated reply remains pending");((JCheckBox)FeatureTest.field(app[0],"toolsBox")).setSelected(false);FeatureTest.call(app[0],"prepareModeContext",new Class<?>[]{});FeatureTest.call(app[0],"renderHistory",new Class<?>[]{});check(!FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting()&&server.requests.size()==2,"Normal mode excludes old MBS choices without inference");check(AttachmentTest.state(app[0]).interactionReplyDraft,"mode changes preserve the generated origin of a pending draft");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(Window w:Window.getWindows())w.dispose();});}
  System.out.println("PASS: "+checks+" composer interaction checks; explicit choices, free text, pending draft, Tab/Undo, per-chat persistence and no mutation before confirmation");System.exit(0);
 }
}
